package com.smarthealth.model;
import java.time.LocalDateTime;import java.util.Objects;
/** Validated vital signs sample. */
public class SensorData {private long id,patientId;private int heartRate,systolicBP,diastolicBP,spo2;private LocalDateTime timestamp;private String source;
 public SensorData(){}public SensorData(long id,long patientId,int heartRate,int systolicBP,int diastolicBP,int spo2,LocalDateTime timestamp,String source){this.id=id;this.patientId=patientId;setHeartRate(heartRate);setSystolicBP(systolicBP);setDiastolicBP(diastolicBP);setSpo2(spo2);this.timestamp=timestamp;this.source=source;}
 public long getId(){return id;}public void setId(long v){id=v;}public long getPatientId(){return patientId;}public void setPatientId(long v){patientId=v;}public int getHeartRate(){return heartRate;}public void setHeartRate(int v){if(v<20||v>250)throw new IllegalArgumentException("Heart rate must be 20-250");heartRate=v;}public int getSystolicBP(){return systolicBP;}public void setSystolicBP(int v){if(v<60||v>260)throw new IllegalArgumentException("Systolic pressure out of range");systolicBP=v;}public int getDiastolicBP(){return diastolicBP;}public void setDiastolicBP(int v){if(v<30||v>160)throw new IllegalArgumentException("Diastolic pressure out of range");diastolicBP=v;}public int getSpo2(){return spo2;}public void setSpo2(int v){if(v<50||v>100)throw new IllegalArgumentException("SpO2 must be 50-100");spo2=v;}public LocalDateTime getTimestamp(){return timestamp;}public void setTimestamp(LocalDateTime v){timestamp=v;}public String getSource(){return source;}public void setSource(String v){source=v;}@Override public String toString(){return "Vitals{HR="+heartRate+", BP="+systolicBP+"/"+diastolicBP+", SpO2="+spo2+"}";}@Override public boolean equals(Object o){return o instanceof SensorData s&&id==s.id;}@Override public int hashCode(){return Objects.hash(id);}}
